package com.example.uniroom;
import android.os.*;import android.graphics.Color;import android.view.*;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import com.example.uniroom.model.Models.*;import com.example.uniroom.network.*;import retrofit2.*;
public class ScheduleActivity extends AppCompatActivity{LinearLayout list;protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_schedule);list=findViewById(R.id.list);Client.api().schedule(new Session(this).id()).enqueue(new Callback<ListResponse<Schedule>>(){public void onResponse(Call<ListResponse<Schedule>> c,Response<ListResponse<Schedule>> r){if(r.body()!=null&&r.body().data!=null)for(Schedule x:r.body().data){TextView v=new TextView(ScheduleActivity.this);v.setText(x.subject_code+" - "+x.subject_name+"\n"+x.day_of_week+" | "+x.start_time+" - "+x.end_time+"\nRoom: "+x.room_name+" • "+x.building+"\nFaculty: "+x.faculty_name);v.setTextSize(16);v.setPadding(18,18,18,18);list.addView(v);}}public void onFailure(Call<ListResponse<Schedule>> c,Throwable t){Toast.makeText(ScheduleActivity.this,"Unable to load schedule",Toast.LENGTH_LONG).show();}});}}
